@app.route('/api/predict', methods=['POST'])
def api_predict():
    try:
        data = request.get_json(force=True) if request.is_json else request.form.to_dict()

        credit_score = float(data.get('credit_score', 650))
        geography = str(data.get('geography', 'France')).capitalize()
        gender_raw = str(data.get('gender', 'Male')).capitalize()
        gender = 1.0 if gender_raw == 'Male' else 0.0
        age = float(data.get('age', 40))
        tenure = float(data.get('tenure', 5))
        balance = float(data.get('balance', 50000))
        num_products = float(data.get('num_products', 1))
        has_crcard = float(data.get('has_crcard', 1))
        is_active = float(data.get('is_active', 1))
        salary = float(data.get('salary', 50000))

        balance_flag = 1.0 if balance == 0 else 0.0
        bal_sal_ratio = math.log1p(balance / salary) if salary > 0 else 0.0

        if age <= 24:
            age_group = 'Young Adults'
        elif age <= 59:
            age_group = 'Middle aged'
        else:
            age_group = 'Senior'

        cs_age_ratio = credit_score / age if age > 0 else 0.0
        ten_age_ratio = tenure / age if age > 0 else 0.0
        active_num_products = float(int(is_active * num_products))

        float_features = [
            credit_score, gender, age, tenure, balance,
            num_products, has_crcard, is_active, salary,
            balance_flag, bal_sal_ratio, cs_age_ratio,
            ten_age_ratio, active_num_products
        ]
        cat_features = [geography, age_group]

        raw_logit = apply_catboost_model(float_features, cat_features)
        prob_churn = 1.0 / (1.0 + math.exp(-raw_logit))
        prob_retain = 1.0 - prob_churn
        prediction = 1 if prob_churn >= threshold else 0

        return jsonify({
            'status': 'success',
            'prediction': prediction,
            'prediction_label': 'Likely to Churn' if prediction == 1 else 'Likely to Retain',
            'probability_churn': round(prob_churn * 100, 2),
            'probability_retain': round(prob_retain * 100, 2),
            'threshold': threshold,
            'inputs_processed': {
                'CreditScore': credit_score,
                'Geography': geography,
                'Gender': gender_raw,
                'Age': age,
                'Tenure': tenure,
                'Balance': balance,
                'NumOfProducts': num_products,
                'HasCrCard': 'Yes' if has_crcard == 1 else 'No',
                'IsActiveMember': 'Yes' if is_active == 1 else 'No',
                'EstimatedSalary': salary,
                'Balance_flag': int(balance_flag),
                'Balance_salary_ratio': round(bal_sal_ratio, 4),
                'Age_group': age_group,
                'CreditScore_Age_ratio': round(cs_age_ratio, 4),
                'Tenure_Age_ratio': round(ten_age_ratio, 4),
                'IsActive_NumOfProducts': int(active_num_products)
            }
        })
    except Exception as e:
        return jsonify({'status': 'error', 'message': str(e)}), 400

